import{_ as t,o as a,c as e,ae as o}from"./chunks/framework.8rYXDNLJ.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"reference/troubleshooting.md","filePath":"reference/troubleshooting.md"}'),i={name:"reference/troubleshooting.md"};function n(r,s,l,p,h,d){return a(),e("div",null,[...s[0]||(s[0]=[o(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="desktop-app" tabindex="-1">Desktop App <a class="header-anchor" href="#desktop-app" aria-label="Permalink to &quot;Desktop App&quot;">​</a></h2><h3 id="app-won-t-open-security-warning" tabindex="-1">App won&#39;t open (security warning) <a class="header-anchor" href="#app-won-t-open-security-warning" aria-label="Permalink to &quot;App won&#39;t open (security warning)&quot;">​</a></h3><p><strong>Symptom:</strong> &quot;Portman can&#39;t be opened because Apple cannot check it for malicious software&quot;</p><p><strong>Solution:</strong></p><ol><li>Right-click (Control-click) on Portman.app</li><li>Select &quot;Open&quot; from the menu</li><li>Click &quot;Open&quot; in the dialog</li></ol><p>See <a href="/portman/docs/guide/installation.html">Installation</a> for detailed steps.</p><hr><h3 id="no-ports-showing" tabindex="-1">No ports showing <a class="header-anchor" href="#no-ports-showing" aria-label="Permalink to &quot;No ports showing&quot;">​</a></h3><p><strong>Symptom:</strong> The port list is empty</p><p><strong>Possible causes:</strong></p><ol><li>No services are running</li><li>Permission issue</li></ol><p><strong>Solution:</strong></p><ul><li>Start a dev server (e.g., <code>npx vite</code>) and refresh</li><li>Check if <code>lsof</code> command works in Terminal</li></ul><hr><h3 id="window-doesn-t-appear" tabindex="-1">Window doesn&#39;t appear <a class="header-anchor" href="#window-doesn-t-appear" aria-label="Permalink to &quot;Window doesn&#39;t appear&quot;">​</a></h3><p><strong>Symptom:</strong> App is running (in Dock) but no window</p><p><strong>Solution:</strong></p><ul><li>Click the Dock icon to show the window</li><li>Or use Cmd+Q to quit and relaunch</li></ul><hr><h2 id="mcp-server" tabindex="-1">MCP Server <a class="header-anchor" href="#mcp-server" aria-label="Permalink to &quot;MCP Server&quot;">​</a></h2><h3 id="claude-doesn-t-see-portman-tools" tabindex="-1">Claude doesn&#39;t see Portman tools <a class="header-anchor" href="#claude-doesn-t-see-portman-tools" aria-label="Permalink to &quot;Claude doesn&#39;t see Portman tools&quot;">​</a></h3><p><strong>Symptom:</strong> Claude says it can&#39;t access port information</p><p><strong>Possible causes:</strong></p><ol><li>MCP server not configured</li><li>Configuration file syntax error</li><li>Node.js not installed</li></ol><p><strong>Solutions:</strong></p><ol><li>Verify configuration:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Claude Code</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><ol start="2"><li><p>Check JSON syntax in config file</p></li><li><p>Ensure Node.js 18+ is installed:</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><hr><h3 id="command-not-found-npx" tabindex="-1">&quot;command not found: npx&quot; <a class="header-anchor" href="#command-not-found-npx" aria-label="Permalink to &quot;&quot;command not found: npx&quot;&quot;">​</a></h3><p><strong>Symptom:</strong> MCP server fails to start</p><p><strong>Solution:</strong> Install Node.js from <a href="https://nodejs.org/" target="_blank" rel="noreferrer">nodejs.org</a> or via Homebrew:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span></span></code></pre></div><hr><h3 id="mcp-server-not-updating" tabindex="-1">MCP server not updating <a class="header-anchor" href="#mcp-server-not-updating" aria-label="Permalink to &quot;MCP server not updating&quot;">​</a></h3><p><strong>Symptom:</strong> Using old version of portman-mcp</p><p><strong>Solution:</strong> npx caches packages. Force latest version:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> portman-mcp@latest</span></span></code></pre></div><p>Or update your MCP config to use <code>@latest</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;portman-mcp@latest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><hr><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><p><a href="https://github.com/zeroshotlog/portman/issues" target="_blank" rel="noreferrer">Open an issue on GitHub</a></p>`,45)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
